def examine(obj,parent="",depth=0):
    if depth>3 or not isinstance(obj,dict): return
    for name,value in obj.items():
        key=parent+"."+name if parent else name
        if isinstance(value,str):
            info={"field":key,"type":"str","len":len(value),"newlines":value.count("\\n"),"html_tags":len(re.findall(r"<(?:table|tr|td|th|p|div|br|tbody|thead)\\b",value,re.I)),"has_html_table":bool(re.search(r"<table\\b",value,re.I)),"has_tab":("\\t" in value),"sample":value[:210]}
            print("DETAIL_FIELD="+json.dumps(info,ensure_ascii=False),flush=True)
        elif isinstance(value,dict):
            print("DETAIL_NESTED="+key+" KEYS="+json.dumps(list(value)[:45],ensure_ascii=False),flush=True)
            examine(value,key,depth+1)
        elif isinstance(value,list):
            print("DETAIL_LIST="+key+" COUNT="+str(len(value))+" FIRST_TYPE="+(type(value[0]).__name__ if value else "empty"),flush=True)
            if value and isinstance(value[0],dict):examine(value[0],key+"[0]",depth+1)
